import base64, pathlib, sys

patches = [
    ("pipeline/pipeline_orchestrator.py", "", ""),
    ("pipeline/pipeline_orchestrator.py", "ICAgICAgICAgICAgICAgIGF1dG9fYXBwcm92ZV9vbl9jb21wbGV0ZT1ib29sKGVudHJ5LmdldCgiYXV0b19hcHByb3ZlX29uX2NvbXBsZXRlIiwgRmFsc2UpKSwKICAgICAgICAgICAgKSkKCiAgICAgICAgX3Jhd19kZWZhdWx0cyA9IHJhdy5nZXQoImRlZmF1bHRzIiwge30pLmdldCgiZXh0cmFfYWxsb3dlZFRvb2xzIiwgW10p", ""),
    (".github/scripts/mark-pr-ready.sh", "", ""),
    ("tests/test_orchestrator_logic.py", "ICAgICAgICBtb2NrX2ZhaWxlZC5hc3NlcnRfY2FsbGVkX29uY2UoKQoKICAgIGRlZiB0ZXN0X21hcmtfcHJfcmVhZHlfc2NyaXB0X2V4aXN0cyhzZWxmKTo=", ""),
]

for fpath, ob64, nb64 in patches:
    old = base64.b64decode(ob64).decode()
    new = base64.b64decode(nb64).decode()
    p = pathlib.Path(fpath)
    content = p.read_text()
    if old not in content:
        print(f"SKIP: {fpath} -- old string not found", file=sys.stderr)
        continue
    count = content.count(old)
    if count != 1:
        print(f"FAIL: {fpath} -- old appears {count} times", file=sys.stderr)
        sys.exit(1)
    content2 = content.replace(old, new, 1)
    p.write_text(content2)
    print(f"OK: patched {fpath}")
